using System.IO;using UnityEngine;using UnityEditor;
namespace LWS.TruckTargetLaunch.Editor {
public static class TargetPreviewAuthoring {
 public static void Create(TargetMatch match){Directory.CreateDirectory("Assets/TruckTargetLaunch/Art");var truck=match.racers[0].truck;var p=truck.transform.position;var q=truck.transform.rotation;truck.transform.SetPositionAndRotation(new Vector3(-4,29,94),Quaternion.Euler(-18,6,0));truck.ApplyColor(match.setup.players[0].color);foreach(var wing in match.racers[0].wings)wing.localRotation=Quaternion.identity;var camera=match.broadcast.view;var cp=camera.transform.position;var cq=camera.transform.rotation;var old=camera.targetTexture;var active=RenderTexture.active;var rt=new RenderTexture(768,432,24);rt.Create();camera.targetTexture=rt;camera.transform.SetPositionAndRotation(new Vector3(-45,64,54),Quaternion.LookRotation(new Vector3(3,9,118)-new Vector3(-45,64,54)));camera.Render();RenderTexture.active=rt;var image=new Texture2D(768,432,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,768,432),0,0);image.Apply();string path="Assets/TruckTargetLaunch/Art/Menu Preview.png";File.WriteAllBytes(path,image.EncodeToPNG());Object.DestroyImmediate(image);camera.targetTexture=old;RenderTexture.active=active;rt.Release();Object.DestroyImmediate(rt);camera.transform.SetPositionAndRotation(cp,cq);truck.transform.SetPositionAndRotation(p,q);for(int i=0;i<2;i++)match.racers[0].wings[i].localRotation=Quaternion.Euler(0,0,i==0?-80:80);AssetDatabase.ImportAsset(path);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.mipmapEnabled=false;importer.SaveAndReimport();}
}
}
